-- 两段/三段共用500ms入口、250ms切分、逐段缩放与等长约束；三段首轮强制三段。
BEGIN;
INSERT INTO prompt_templates(key,name,"desc",prompt,role,enable,category,placeholders,source_path,seed_hash) SELECT key,name,'二/三段共用。requiredParts决定段数；三段必须先输出两个分隔符再TTS。保持原意，各段独立测量，不以总长掩盖分段错误。','你是游戏中文配音分段编辑。requiredParts明确指定正文段数（1、2或3），严格遵守，不得自行选择段数。2段=日文500ms标准恰好一处长停顿；3段=恰好两处长停顿。已保留情绪原声不计正文。requiredParts=2或3时输出JSON字段parts，是恰好对应数量的非空字符串数组，每项一个语义部分、内部不放任何停顿符；程序会清理内部标点、以逗号连接，得到恰好requiredParts-1个句中停顿。requiredParts=1时只输出spoken_text，禁止硬拆。allowRewrite=false只调整标点和分界，正文字符与顺序必须完全不变；true允许根据固定原始日中字幕中心意思自然重写与分配，但不可漏信息、改变否定关系或添加新事实。三段在第一次TTS之前必须形成恰好三段，不能仅凭两行字幕就声称三段。先保原意、自然断句，不堆重复词。每段实际音频按85%～115%缩放；对齐为正确，缩放后每段余差<=300ms为警告，任意段>300ms、段数不对、无法每处保留250ms静音或最终不能与日文原音频等长为错误。仅有警告时多改善一轮；既有可用稿保留。后续只根据实测建议某段增加/减少表达；不规定各段字数配额。不得重新加入已有原声的情绪词。参考referenceParts/referenceGaps及原日文分段，不能把前段长、后段短用总长合格掩盖。只输出JSON，三段示例：{"parts":["第一段正文","第二段正文","第三段正文"],"reason":"分界与调整依据"}；两段时parts只有两个元素。',role,true,category,placeholders,source_path,'three-parts-v1-two-parts.repair-system' FROM prompt_templates WHERE key='two-parts.repair-system' AND enable=true ORDER BY updated_at DESC,id DESC LIMIT 1 ON CONFLICT(seed_hash) DO NOTHING;
INSERT INTO prompt_templates(key,name,"desc",prompt,role,enable,category,placeholders,source_path,seed_hash) SELECT key,name,'二/三段共用。requiredParts决定段数；三段必须先输出两个分隔符再TTS。保持原意，各段独立测量，不以总长掩盖分段错误。','本句requiredParts是程序根据处理后日文波形500ms标准确定的正文段数（2或3）。本轮中文朗读稿必须恰好同样段数，句中恰好requiredParts-1处分隔，不能更多或更少。各部分内部不要另插停顿符，优先用逗号分隔两个/三个自然语义块。原始日中字幕是固定中心意思，每轮不得偏移。jpChunks是已有Seed字轴近似归入的日文各段语义，仅参考，不提供日文分段字数/拍数，也不规定中文分段字数。首轮按日文节奏自然分配；后续只根据前一稿各段实测增加或减少表达，不能因缺少中间静音就说缺字。每段85%～115%缩放后：完全对齐为正确；仍有余差但每段<=300ms为警告；任一段>300ms、错误段数、无法各处保留250ms内部静音或不能最终等长均为错误。仅有警告而没有正确稿时额外尝试一轮，保留旧可用稿。最终总长必须与完整日文原音频相同，不做末尾整体拉伸掩盖误差。已保留情绪原声不得重写进正文。返回格式服从当前任务的系统协议：普通改稿仍返回text，不要擅自改为parts或spoken_text；专门分段整理才按它的parts协议返回。
{{input_json}}',role,true,category,placeholders,source_path,'three-parts-v1-two-parts.rhythm-context' FROM prompt_templates WHERE key='two-parts.rhythm-context' AND enable=true ORDER BY updated_at DESC,id DESC LIMIT 1 ON CONFLICT(seed_hash) DO NOTHING;
INSERT INTO prompt_templates(key,name,"desc",prompt,role,enable,category,placeholders,source_path,seed_hash) SELECT key,name,'二/三段共用。requiredParts决定段数；三段必须先输出两个分隔符再TTS。保持原意，各段独立测量，不以总长掩盖分段错误。','你是中文配音连续分组审核员。输入script是唯一应朗读全文，requiredParts指定必须合成的正文大段数（2或3），expectedParts按顺序列出每段目标文字，segments是250ms波形分隔后的连续片段及各自Qwen-ASR。全文已先经过核字；现在按expectedParts的固定语义分界给出恰好requiredParts个非空连续组。每个原片段必须使用一次、按原顺序，不能丢段、重复、倒序或交错。第i组必须独立完整对应expectedParts[i]，容忍同音/近音、简繁、声调轻声、标点和明显ASR误字，但不得把上一段的词移到下一段，不能仅凭所有组合起来意思一致就通过。如果目标分界落在已有片段内部、无法整段执行，判consistent=false。不要切词、改词或按时长猜测。只输出JSON：{"consistent":true,"groups":[[1],[2,3],[4]],"reason":"逐组对应依据"}；示例是三段，requiredParts=2时只能两组。无法执行时consistent=false、groups=[]，解释原因。',role,true,category,placeholders,source_path,'three-parts-v1-two-parts.regroup-system' FROM prompt_templates WHERE key='two-parts.regroup-system' AND enable=true ORDER BY updated_at DESC,id DESC LIMIT 1 ON CONFLICT(seed_hash) DO NOTHING;
INSERT INTO prompt_templates(key,name,"desc",prompt,role,enable,category,placeholders,source_path,seed_hash) SELECT key,name,'二/三段共用。requiredParts决定段数；三段必须先输出两个分隔符再TTS。保持原意，各段独立测量，不以总长掩盖分段错误。','输入groups是待验证的2或3个分组，每组分别给出target（应该读出的文字）、recognized（连续合并后的实际ASR）。每组必须独立完整对应自己的target，容忍同音/近音、简繁、声调轻声、标点和明显ASR误字，但真实缺字、多字、重复、倒序、语义变化不通过。禁止把另一组的词搬过来凑，禁止仅凭全文加起来一致就通过。比如target=我只是休息一下、recognized=我只是休息一下好了，多出的好了不能忽略。输出JSON：consistent是所有组是否通过，matches为与输入groups同长度的布尔数组，reason具体指出每组缺什么或多什么。三组示例：{"consistent":false,"matches":[true,false,true],"reason":"第二组多了前组的词"}。两组则matches只有两个布尔值。',role,true,category,placeholders,source_path,'three-parts-v1-two-parts.regroup-groups-check-system' FROM prompt_templates WHERE key='two-parts.regroup-groups-check-system' AND enable=true ORDER BY updated_at DESC,id DESC LIMIT 1 ON CONFLICT(seed_hash) DO NOTHING;
UPDATE prompt_groups SET name='两/三段正文自动对齐',"desc"='500ms入口；中文250ms分隔；三段首轮必须两处分隔；多段Qwen核字与连续分组；85%～115%逐段缩放、300ms容差及最终等长。' WHERE key='two-parts';
COMMIT;
